import "./home.css";
import Banner from "./assets/banner.png";
import Logo from "./assets/logo.png";
import p1 from "./assets/hoodie.png";
import { User } from "lucide-react"; // Only keep User icon
import { useState } from "react";
import LanguageSelector from "./assets/languageSelector.jsx";

const HomePage = () => {
  const [language, setLanguage] = useState("en-US");
  return (
    <div>
      {/* Navigation Bar */}
      <nav className="nav-bar">
        <div id="logo">
          <img src={Logo} alt="logo" />
        </div>
        <div id="nav-bar-menu-left">
          <button>Stories</button>
          <button>News</button>
          <button>About Us</button>
        </div>
        <div id="nav-bar-menu-right">
          {/* 🌍 Language Selector replaces Cart */}
          <LanguageSelector
            language={language}
            onChange={setLanguage} // directly update state
          />
        </div>
      </nav>

      <section className="top-info">
        <p>hi</p>
        <p>hi</p>
        <button>View</button>
        <button>Try app</button>
      </section>
      <section id="introduce">
        <div className="introduce-top">
          <div class="introduce-col-right">
            <h2>Left Column</h2>
            <p>Some text or image here.</p>
          </div>
          <div class="introduce-col-left">
            <h2>Right Column</h2>
            <p>Another text or image here.</p>
          </div>
        </div>
        <div className="introduce-bottom">
          <p>HEllo</p>
        </div>
      </section>

      {/* Product Slides */}
      <ProductSection title="New & Featured" products={[p1, p1, p1]} />
    </div>
  );
};

const ProductSection = ({ title, products }) => (
  <section className="product-slide">
    <div className="title">
      <h1>{title}</h1>
      <button>Explore more</button>
    </div>
    <div className="product-grid">
      {products.map((product, index) => (
        <ProductBox key={index} image={product} />
      ))}
    </div>
  </section>
);

const ProductBox = ({ image }) => (
  <div className="product-box">
    <img src={image} alt="Product" />
    <div className="product-box-info">
      <p>DIOR AND HYLTON NEL Hooded Sweatshirt</p>
      <p>AU$ 2,500.00</p>
    </div>
  </div>
);

export default HomePage;
